package cn.fireassistant;

import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static cn.fireassistant.Store.*;

@Service
public class TaskService {
    final Store db;final AuthService auth;private final AdminService admin;private final DemoData demo;
    TaskService(Store db,AuthService auth,AdminService admin,DemoData demo){this.db=db;this.auth=auth;this.admin=admin;this.demo=demo;}
    boolean allowed(Map<String,Object> task){var user=auth.current();if(!user.get("orgId").equals(task.get("orgId")))return false;return switch(user.get("role").toString()){case "ADMIN"->true;case "INSPECTOR"->user.get("id").equals(task.get("inspectorId"));case "REVIEWER"->user.get("id").equals(task.get("reviewerId"))&&Set.of("待审核","整改中","已完成").contains(task.get("status"));case "RECHECKER"->user.get("id").equals(task.get("recheckerId"))&&Set.of("整改中","已完成").contains(task.get("status"));default->false;};}
    void scope(Map<String,Object> task){if(!allowed(task))throw Api.error(404,"任务不存在或未分配给当前人员");}
    public Map<String,Object> task(String id){var task=db.one("inspect_task",id);scope(task);return task;}
    Map<String,Object> lock(String id,Map<String,Object> body,String... roles){auth.require(roles);var task=db.taskLock(id);scope(task);version(task,body);return task;}
    static void status(Map<String,Object> task,String... statuses){if(!Arrays.asList(statuses).contains(task.get("status")))throw Api.error(409,"任务阶段已改变，请查看最新任务");}
    public List<Map<String,Object>> tasks(){return db.list("inspect_task","WHERE org_id=? ORDER BY updated_at DESC,id",auth.current().get("orgId")).stream().filter(this::allowed).toList();}
    List<Map<String,Object>> items(String taskId){return db.list("checklist_item","WHERE task_id=? ORDER BY id",taskId);}
    List<Map<String,Object>> issues(String taskId){return db.list("issue_record","WHERE task_id=? ORDER BY id",taskId);}
    List<Map<String,Object>> risks(String taskId){return db.list("risk_event","WHERE task_id=? ORDER BY id",taskId);}
    public Map<String,Object> detail(String id){var task=task(id);var result=new LinkedHashMap<>(task);result.put("unit",admin.unit(task.get("unitId").toString()));result.put("checklist",items(id));result.put("issues",issues(id));result.put("events",risks(id));result.put("history",history(id));return result;}
    public Map<String,Object> history(String id){task(id);return map("reviews",db.list("review_record","WHERE task_id=? ORDER BY created_at,id",id),"rectifications",db.list("rectification_record","WHERE task_id=? ORDER BY created_at,id",id),"rechecks",db.list("recheck_record","WHERE task_id=? ORDER BY created_at,id",id),"logs",db.list("operate_log","WHERE task_id=? ORDER BY created_at,id",id));}
    public Map<String,Object> state(){var tasks=tasks();var checklists=new LinkedHashMap<String,Object>();var issues=new ArrayList<Map<String,Object>>();var events=new ArrayList<Map<String,Object>>();for(var task:tasks){String id=task.get("id").toString();checklists.put(id,items(id));issues.addAll(issues(id));events.addAll(risks(id));}return map("user",auth.current(),"tasks",tasks,"units",admin.units(),"checklists",checklists,"issues",issues,"events",events);}
    boolean actionable(Map<String,Object> task){return switch(auth.current().get("role").toString()){case "INSPECTOR"->Set.of("待检查","进行中").contains(task.get("status"));case "REVIEWER"->task.get("status").equals("待审核");case "RECHECKER"->task.get("status").equals("整改中");default->!task.get("status").equals("已完成");};}
    public Map<String,Object> dashboard(){var tasks=tasks();var pending=tasks.stream().filter(this::actionable).toList();var priority=pending.stream().sorted(Comparator.<Map<String,Object>>comparingInt(t->t.get("risk").toString().contains("高")?0:t.get("risk").toString().contains("中")?1:2).thenComparing(t->OffsetDateTime.parse(t.get("due").toString()).toInstant())).limit(3).toList();var active=tasks.stream().flatMap(t->risks(t.get("id").toString()).stream()).filter(this::activeRisk).toList();return map("pending",tasks.stream().filter(t->t.get("status").equals("待检查")).count(),"inProgress",tasks.stream().filter(t->t.get("status").equals("进行中")).count(),"review",tasks.stream().filter(t->t.get("status").equals("待审核")).count(),"rectifying",tasks.stream().filter(t->t.get("status").equals("整改中")).count(),"completed",tasks.stream().filter(t->t.get("status").equals("已完成")).count(),"reviewed",tasks.stream().filter(t->Set.of("整改中","已完成").contains(t.get("status"))).count(),"highRisk",active.stream().filter(e->e.get("level").equals("high")).count(),"priorityTasks",priority,"unfinishedTotal",pending.size());}
    boolean activeRisk(Map<String,Object> risk){return !Set.of("复查合格","已排除").contains(risk.get("state").toString());}
    public Map<String,Object> unitDetail(String id){var result=new LinkedHashMap<>(admin.unit(id));var tasks=tasks().stream().filter(t->t.get("unitId").equals(id)).toList();result.put("tasks",tasks);result.put("issues",tasks.stream().flatMap(t->issues(t.get("id").toString()).stream()).toList());result.put("events",tasks.stream().flatMap(t->risks(t.get("id").toString()).stream()).filter(this::activeRisk).toList());return result;}
    Map<String,Object> savedOption(Map<String,Object> row,String source){return map("id",row.get("id"),"title",row.get("title"),"tip",row.get("tip"),"group","自定义检查","custom",true,"status",null,"note","","basis","","basisVersion","custom-v1","applicableScene",row.get("unit_type"),"source",source);}
    @Transactional public void deleteChecklistItem(String id,String unitId,String source){
        auth.require("ADMIN");String org=auth.current().get("orgId").toString();
        if(id.startsWith("saved-item-")){if(db.jdbc.update("DELETE FROM saved_checklist_item WHERE id=? AND org_id=?",id,org)!=1)throw Api.error(404,"检查项目不存在或无权删除");return;}
        if(unitId==null||source==null)throw Api.error(404,"检查项目不存在或无权删除");
        checklistOptions(unitId,source);var unit=admin.unit(unitId);
        if(availableChecklist(unit,source).stream().noneMatch(item->id.equals(item.get("id"))))throw Api.error(404,"检查项目不存在或无权删除");
        db.jdbc.update("INSERT INTO removed_checklist_template(org_id,unit_type,template_id) VALUES(?,?,?)",org,unit.get("type"),id);
    }
    List<Map<String,Object>> availableChecklist(Map<String,Object> unit,String source){
        var removed=new HashSet<>(db.jdbc.queryForList("SELECT template_id FROM removed_checklist_template WHERE org_id=? AND unit_type=?",String.class,auth.current().get("orgId"),unit.get("type")));
        var options=new ArrayList<>(demo.template(unit.get("type").toString(),source).stream().filter(item->!removed.contains(item.get("id"))).toList());
        for(var row:db.jdbc.queryForList("SELECT id,unit_type,title,tip FROM saved_checklist_item WHERE org_id=? AND unit_type=? ORDER BY created_at,id",auth.current().get("orgId"),unit.get("type")))options.add(savedOption(row,source));return options;
    }
    public List<Map<String,Object>> checklistOptions(String unitId,String source){auth.require("ADMIN");var unit=admin.unit(unitId);if(!Boolean.TRUE.equals(unit.get("active")))throw Api.error(400,"单位已停用");if(!Set.of("设施异常触发","日常抽查","历史隐患复查","专项检查").contains(source))throw Api.error(400,"无效任务来源");return availableChecklist(unit,source);}
    @Transactional public Map<String,Object> saveChecklistItem(Map<String,Object> body){auth.require("ADMIN");var unit=admin.unit(text(body,"unitId",80));if(!Boolean.TRUE.equals(unit.get("active")))throw Api.error(400,"单位已停用");String title=text(body,"title",200),tip=text(body,"tip",1000),org=auth.current().get("orgId").toString();db.jdbc.update("INSERT INTO saved_checklist_item(id,org_id,unit_type,title,tip) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",Store.id("saved-item"),org,unit.get("type"),title,tip);var row=db.jdbc.queryForMap("SELECT id,unit_type,title,tip FROM saved_checklist_item WHERE org_id=? AND unit_type=? AND title=?",org,unit.get("type"),title);if(!tip.equals(row.get("tip")))throw Api.error(409,"已有同名项目但检查要求不同，请修改项目名称");return savedOption(row,"日常抽查");}
    List<Map<String,Object>> selectedChecklist(Map<String,Object> body,Map<String,Object> unit,String source){
        var options=availableChecklist(unit,source);List<String> ids;
        if(body.containsKey("checklistIds")){if(!(body.get("checklistIds") instanceof List<?> values)||values.size()>50)throw Api.error(400,"检查项目最多五十项");ids=values.stream().map(value->{if(!(value instanceof String id)||id.isBlank()||id.length()>120)throw Api.error(400,"检查项目编号不正确");return id;}).distinct().toList();}else ids=options.stream().filter(item->!Boolean.TRUE.equals(item.get("custom"))).map(item->item.get("id").toString()).toList();
        if(ids.stream().anyMatch(id->options.stream().noneMatch(item->id.equals(item.get("id")))))throw Api.error(400,"所选检查项目不属于当前单位的可选清单，请重新选择");
        var items=new ArrayList<Map<String,Object>>();for(var option:options)if(ids.contains(option.get("id"))){var item=new LinkedHashMap<>(option);item.put("templateId",option.get("id"));items.add(item);}
        Object raw=body.getOrDefault("customItems",List.of());if(!(raw instanceof List<?> customs)||customs.size()>10)throw Api.error(400,"自定义检查项目最多十项");
        for(Object rawItem:customs){if(!(rawItem instanceof Map<?,?> fields))throw Api.error(400,"自定义检查项目格式不正确");var custom=new LinkedHashMap<String,Object>();fields.forEach((key,value)->custom.put(String.valueOf(key),value));items.add(map("title",text(custom,"title",200),"group","自定义检查","tip",text(custom,"tip",1000),"status",null,"note","","basis","","basisVersion","custom-v1","applicableScene",unit.get("type"),"source",source));}
        if(items.isEmpty())throw Api.error(400,"请至少选择或添加一个检查项目");if(items.size()>50)throw Api.error(400,"检查项目最多五十项");return items;
    }
    @Transactional public Map<String,Object> create(Map<String,Object> body){
        auth.require("ADMIN");var unit=admin.unit(text(body,"unitId",80));if(!Boolean.TRUE.equals(unit.get("active")))throw Api.error(400,"单位已停用");
        String source=text(body,"source",100);if(!Set.of("设施异常触发","日常抽查","历史隐患复查","专项检查").contains(source))throw Api.error(400,"无效任务来源");
        String inspector=text(body,"inspectorId",80),reviewer=text(body,"reviewerId",80),rechecker=text(body,"recheckerId",80);admin.assigned(inspector,"INSPECTOR");admin.assigned(reviewer,"REVIEWER");admin.assigned(rechecker,"RECHECKER");
        String risk=body.containsKey("risk")?text(body,"risk",20):unit.get("risk").toString();if(!Set.of("高风险关注","中风险关注","低风险").contains(risk))throw Api.error(400,"无效风险标签");
        String due=futureDue(text(body,"due",80));var focus=strings(body,"focus");if(focus.isEmpty())focus=List.of(switch(source){case "设施异常触发"->"核验异常设施运行及现场事实";case "历史隐患复查"->"回看历史问题并核对整改情况";case "专项检查"->"核对专项检查要求和重点项目";default->"核对单位场所条件及常规消防安全事项";});
        var selected=selectedChecklist(body,unit,source);
        String id="XF-"+java.time.LocalDate.now().toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,6).toUpperCase();
        var task=map("id",id,"unitId",unit.get("id"),"orgId",auth.current().get("orgId"),"source",source,"risk",risk,"due",due,"focus",focus,"inspectorId",inspector,"reviewerId",reviewer,"recheckerId",rechecker,"status","待检查","version",0,"progress",0,"site",null,"createdAt",now(),"updatedAt",now());
        db.insert("inspect_task",task,map("unit_id",unit.get("id"),"org_id",task.get("orgId"),"inspector_id",inspector,"reviewer_id",reviewer,"rechecker_id",rechecker,"status","待检查","version",0));
        for(var template:selected){var item=new LinkedHashMap<>(template);item.put("id",Store.id("item"));item.put("taskId",id);db.insert("checklist_item",item,map("task_id",id));}
        if(source.equals("设施异常触发")){String level=risk.contains("高")?"high":risk.contains("中")?"medium":"low";var event=map("id",Store.id("event"),"unitId",unit.get("id"),"taskId",id,"issueId",null,"title",focus.get(0),"source","人工录入异常线索","detail","等待现场核验与人工审核","level",level,"state","待核验","time",now(),"updatedAt",now());db.insert("risk_event",event,map("unit_id",unit.get("id"),"task_id",id,"issue_id",null,"state","待核验"));}
        db.log(auth.current(),id,"创建并分配任务",map("source",source));return task;
    }
    static String date(String value){try{return OffsetDateTime.parse(value).toString();}catch(Exception ex){throw Api.error(400,"时间无效，请重新选择");}}
    static String futureDue(String value){String parsed=date(value);if(!OffsetDateTime.parse(parsed).toInstant().isAfter(Instant.now()))throw Api.error(400,"检查期限必须晚于当前时间，请重新选择");return parsed;}
    @Transactional public Map<String,Object> edit(String id,Map<String,Object> body){var task=lock(id,body,"ADMIN");status(task,"待检查");if(body.containsKey("due"))task.put("due",futureDue(text(body,"due",80)));if(body.containsKey("focus")){var focus=strings(body,"focus");if(focus.isEmpty())throw Api.error(400,"检查重点不能为空");task.put("focus",focus);}for(var role:Map.of("inspectorId","INSPECTOR","reviewerId","REVIEWER","recheckerId","RECHECKER").entrySet())if(body.containsKey(role.getKey())){String user=text(body,role.getKey(),80);admin.assigned(user,role.getValue());task.put(role.getKey(),user);}db.saveTask(task);db.log(auth.current(),id,"调整任务安排",body);return task;}
    @Transactional public Map<String,Object> start(String id,Map<String,Object> body){var task=lock(id,body,"INSPECTOR");status(task,"待检查");task.put("status","进行中");task.put("startedAt",now());db.saveTask(task);db.log(auth.current(),id,"开始现场检查",Map.of());return task;}
    @Transactional public Map<String,Object> site(String id,Map<String,Object> body){var task=lock(id,body,"INSPECTOR");status(task,"进行中");var site=map("type",text(body,"type",80),"height",number(body,"height",0,1000,false),"floors",number(body,"floors",1,300,true),"people",number(body,"people",0,10000000,true),"checkedBy",auth.current().get("name"),"checkedAt",now());task.put("site",site);db.saveTask(task);db.log(auth.current(),id,"保存场所核对",site);return task;}
    static Number number(Map<String,Object> body,String key,double min,double max,boolean integer){if(!(body.get(key)instanceof Number value)||!Double.isFinite(value.doubleValue())||value.doubleValue()<min||value.doubleValue()>max||(integer&&value.doubleValue()!=value.intValue()))throw Api.error(400,label(key)+"无效，请检查数值及允许范围");return integer?value.intValue():value.doubleValue();}
    @Transactional public Map<String,Object> checklist(String id,String itemId,Map<String,Object> body){var task=lock(id,body,"INSPECTOR");status(task,"进行中");var item=db.one("checklist_item",itemId);if(!item.get("taskId").equals(id))throw Api.error(404,"检查项目不存在");String value=text(body,"status",20);if(!Set.of("normal","abnormal","pending","na").contains(value))throw Api.error(400,"无效检查结论");String note=optional(body,"note",1000);if(value.equals("na")&&note.isEmpty())throw Api.error(400,"不适用必须填写原因");if(!value.equals("abnormal")&&issues(id).stream().anyMatch(i->i.get("itemId").equals(itemId)&&!i.get("status").equals("已排除")))throw Api.error(409,"项目已有问题记录，不能直接改为其他结论");item.put("status",value);item.put("note",note);item.put("recordedBy",auth.current().get("name"));item.put("recordedAt",now());db.save("checklist_item",item,Map.of());var items=items(id);task.put("progress",Math.round(items.stream().filter(i->i.get("status")!=null).count()*100f/items.size()));db.saveTask(task);db.log(auth.current(),id,"记录检查结论",map("itemId",itemId,"status",value));return task;}
    @Transactional public Map<String,Object> submit(String id,Map<String,Object> body){var task=lock(id,body,"INSPECTOR");status(task,"进行中");var items=items(id);var issues=issues(id);if(items.isEmpty())throw Api.error(400,"任务没有检查清单");var missing=new ArrayList<String>();for(var item:items){String title=item.get("title").toString();if(item.get("status")==null||item.get("status").equals("pending"))missing.add(title+"：未完成核验");else if(item.get("status").equals("na")&&optional(item,"note",1000).isEmpty())missing.add(title+"：缺少不适用原因");else if(item.get("status").equals("abnormal")&&issues.stream().noneMatch(i->i.get("itemId").equals(item.get("id"))))missing.add(title+"：缺少问题记录");}if(!missing.isEmpty())throw Api.error(400,"请补齐以下内容：\n"+String.join("\n",missing));for(var issue:issues)if(issue.get("status").equals("已退回")){issue.put("status","待审核");db.save("issue_record",issue,map("status","待审核"));}task.put("status","待审核");task.put("submittedAt",now());db.saveTask(task);db.log(auth.current(),id,"提交人工审核",map("issues",issues.size()));return task;}
}
